# Check what commits are on GitHub right now via API
curl -s -m 10 "https://api.github.com/repos/ibb142/ivx-holdings-platform/commits?per_page=3" 2>&1 | python3 -c "
import sys,json
data = sys.stdin.read()
try:
    commits = json.loads(data)
    if isinstance(commits, list):
        for c in commits:
            print(f'{c[\"sha\"][:12]} {c[\"commit\"][\"message\"].split(chr(10))[0][:80]}')
    else:
        print(f'Error: {data[:300]}')
except Exception as e:
    print(f'Parse error: {e}')
    print(data[:300])
" 2>&1

